// Generates the website platform config.
//
// The generated file (website/config.js) IS committed, so a deployment serves it
// as a plain static file and never depends on a build step. Run this manually
// when the API base URL changes:
//
//   API_BASE_URL=https://<host> node website/gen-config.mjs
//
// Pass an output directory as the first argument to write somewhere else
// (CI uses a temp dir so it never rewrites the committed config).
//
// Required env: API_BASE_URL (or VITE_API_BASE_URL)
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const here = path.dirname(fileURLToPath(import.meta.url))
const outDir = process.argv[2] ? path.resolve(process.argv[2]) : here
const outFile = path.join(outDir, 'config.js')

const apiBaseUrl = (process.env.API_BASE_URL || process.env.VITE_API_BASE_URL || '').trim()

const contents = `// Generated by website/gen-config.mjs — committed on purpose so the site needs
// no build step. Regenerate with API_BASE_URL set when the API host changes.
window.ALPHA_PLATFORM = ${JSON.stringify({ apiBaseUrl }, null, 2)}
`

fs.mkdirSync(outDir, { recursive: true })
fs.writeFileSync(outFile, contents, 'utf8')
if (!apiBaseUrl) {
  console.warn(`[gen-config] API_BASE_URL not set — wrote an unconfigured config to ${outFile}`)
} else {
  console.log(`[gen-config] wrote ${outFile}`)
}
